        points=[P("the particles move randomly at high speed in all directions", ["random", "all directions", "high speed", "fast", "freely"]),
                P("the forces between them are negligible / they are far apart, so nothing holds them together", ["negligible", "very weak", "no forces", "far apart", "nothing holds", "not attracted", "almost no forces"]),
                P("so they travel until they hit the walls and occupy the whole space", ["hit the walls", "collide with the walls", "whole space", "all the space", "every part", "entire container", "fill"])],
        min_points=2,
