        hints=["Think about how the particles move and whether anything pulls them back together.",
               "Fast, random motion plus almost no attraction between particles.",
               "Particles move ___ in all directions; forces are ___; they spread to the ___ ."],
        keywords="random high-speed motion, negligible forces, fill the whole space",
        figure=lambda: sketches.particles("gas", "gas"),
